def transform(grid):
    out=[row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen=set()
    # Each nonzero rectangle object is separated from others by zero background;
    # determine colored nested rectangular bands and reverse their band colors.
    for r in range(h):
      for c in range(w):
        if grid[r][c] == 0 or (r,c) in seen:
          continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        t=min(y for y,x in cells); b=max(y for y,x in cells)
        l=min(x for y,x in cells); rr=max(x for y,x in cells)
        boxes=[]; colors=[]
        while t<=b and l<=rr:
          border=[grid[y][x] for y in range(t,b+1) for x in range(l,rr+1)
                  if y in (t,b) or x in (l,rr)]
          if not border or len(set(border))!=1:
            break
          boxes.append((t,b,l,rr)); colors.append(border[0])
          t+=1; b-=1; l+=1; rr-=1
        for (t,b,l,rr), color in zip(boxes, reversed(colors)):
          # Only repaint cells of this particular layer's original color.
          for y in range(t,b+1):
            for x in range(l,rr+1):
              if grid[y][x] == color:
                out[y][x]=color
    return out
